// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 t, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        // Rule: after Put, the stored unlockTime must never lie in the past
        // (it must be clamped to at least the current block timestamp).
        (uint unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
